import React, { useState, useEffect } from 'react';
import { Link, useParams, useNavigate } from 'react-router-dom';
import { getRecipeById, parseRecipeMarkdown } from '../data/recipeProcessor';

const RecipeDetailPage = () => {
  const { recipeId } = useParams();
  const navigate = useNavigate();
  const [recipe, setRecipe] = useState(null);
  const [recipeDetails, setRecipeDetails] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [activeTab, setActiveTab] = useState('ingredients');

  useEffect(() => {
    const loadRecipe = async () => {
      setLoading(true);
      setError(null);

      // Get basic recipe info
      const basicRecipe = getRecipeById(recipeId);
      if (!basicRecipe) {
        setError('Recipe not found');
        setLoading(false);
        return;
      }

      setRecipe(basicRecipe);

      // Parse detailed recipe content from markdown
      try {
        const details = await parseRecipeMarkdown(recipeId);
        if (details) {
          setRecipeDetails(details);
        } else {
          setError('Could not load recipe details');
        }
      } catch (err) {
        console.error('Error loading recipe details:', err);
        setError('Could not load recipe details');
      }

      setLoading(false);
    };

    if (recipeId) {
      loadRecipe();
    }
  }, [recipeId]);

  const getDifficultyColor = (difficulty) => {
    switch (difficulty?.toLowerCase()) {
      case 'easy': return '#28a745';
      case 'medium': return '#ffc107';
      case 'hard': return '#dc3545';
      default: return '#6c757d';
    }
  };

  const getCategoryIcon = (category) => {
    switch (category) {
      case 'Main Dish': return '🍽️';
      case 'Side Dish': return '🥘';
      case 'Appetizer': return '🥟';
      case 'Beverage': return '🥤';
      case 'Condiment': return '🧄';
      default: return '🍴';
    }
  };

  const handlePrint = () => {
    window.print();
  };

  if (loading) {
    return (
      <div className="container">
        <div className="loading-message">
          <h3>🔄 Loading recipe...</h3>
          <p>Please wait while we fetch the recipe details.</p>
        </div>
      </div>
    );
  }

  if (error || !recipe) {
    return (
      <div className="container">
        <Link to="/recipes" className="back-button">
          <i className="fas fa-arrow-left"></i> Back to Recipes
        </Link>
        <div className="error-message">
          <h3>❌ {error || 'Recipe not found'}</h3>
          <p>The recipe you're looking for doesn't exist or couldn't be loaded.</p>
          <button className="btn btn-primary" onClick={() => navigate('/recipes')}>
            Browse All Recipes
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="container recipe-detail">
      <Link to="/recipes" className="back-button">
        <i className="fas fa-arrow-left"></i> Back to Recipes
      </Link>

      {/* Recipe Header */}
      <div className="recipe-detail-header">
        <div className="recipe-detail-image">
          <img
            src={recipe.image}
            alt={recipe.name}
            onError={(e) => {
              e.target.src = '/recipes/images/default-recipe.jpg';
            }}
          />
        </div>

        <div className="recipe-detail-info">
          <div className="recipe-category-tag">
            {getCategoryIcon(recipe.category)} {recipe.category}
          </div>

          <h1>{recipe.name}</h1>
          <p className="recipe-description-large">{recipe.description}</p>

          <div className="recipe-meta-grid">
            <div className="recipe-meta-item">
              <i className="fas fa-clock"></i>
              <div>
                <strong>Cooking Time</strong>
                <span>{recipe.cookingTime}</span>
              </div>
            </div>
            <div className="recipe-meta-item">
              <i className="fas fa-users"></i>
              <div>
                <strong>Servings</strong>
                <span>{recipe.servings}</span>
              </div>
            </div>
            <div className="recipe-meta-item">
              <i className="fas fa-signal"></i>
              <div>
                <strong>Difficulty</strong>
                <span
                  className="difficulty-badge"
                  style={{ backgroundColor: getDifficultyColor(recipe.difficulty) }}
                >
                  {recipe.difficulty}
                </span>
              </div>
            </div>
          </div>

          <div className="recipe-actions">
            <button className="btn btn-outline-primary" onClick={handlePrint}>
              <i className="fas fa-print"></i> Print Recipe
            </button>
          </div>
        </div>
      </div>

      {/* Recipe Content Tabs */}
      {recipeDetails && (
        <div className="recipe-content">
          <div className="recipe-tabs">
            <button
              className={`tab-button ${activeTab === 'ingredients' ? 'active' : ''}`}
              onClick={() => setActiveTab('ingredients')}
            >
              <i className="fas fa-list"></i> Ingredients
            </button>
            <button
              className={`tab-button ${activeTab === 'instructions' ? 'active' : ''}`}
              onClick={() => setActiveTab('instructions')}
            >
              <i className="fas fa-tasks"></i> Instructions
            </button>
            {recipeDetails.notes && recipeDetails.notes.length > 0 && (
              <button
                className={`tab-button ${activeTab === 'notes' ? 'active' : ''}`}
                onClick={() => setActiveTab('notes')}
              >
                <i className="fas fa-sticky-note"></i> Notes
              </button>
            )}
            {recipeDetails.lessonsLearned && recipeDetails.lessonsLearned.length > 0 && (
              <button
                className={`tab-button ${activeTab === 'lessons' ? 'active' : ''}`}
                onClick={() => setActiveTab('lessons')}
              >
                <i className="fas fa-lightbulb"></i> Tips
              </button>
            )}
          </div>

          <div className="tab-content">
            {activeTab === 'ingredients' && (
              <div className="ingredients-section">
                <h3>🛒 Ingredients</h3>
                <div className="ingredients-list">
                  {recipeDetails.ingredients.map((ingredient, index) => (
                    <div key={index} className="ingredient-item">
                      <i className="fas fa-check"></i>
                      <span>{ingredient}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {activeTab === 'instructions' && (
              <div className="instructions-section">
                <h3>👩‍🍳 Instructions</h3>
                <div className="instructions-list">
                  {recipeDetails.instructions.map((instruction, index) => (
                    <div key={index} className="instruction-item">
                      <div className="instruction-number">{index + 1}</div>
                      <div className="instruction-text">
                        {instruction.replace(/^\d+\.\s*/, '')}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {activeTab === 'notes' && recipeDetails.notes && (
              <div className="notes-section">
                <h3>📝 Notes</h3>
                <div className="notes-content">
                  {recipeDetails.notes.map((note, index) => (
                    <p key={index}>{note}</p>
                  ))}
                </div>
              </div>
            )}

            {activeTab === 'lessons' && recipeDetails.lessonsLearned && (
              <div className="lessons-section">
                <h3>💡 Lessons Learned & Tips</h3>
                <div className="lessons-list">
                  {recipeDetails.lessonsLearned.map((lesson, index) => (
                    <div key={index} className="lesson-item">
                      <i className="fas fa-lightbulb"></i>
                      <span>{lesson}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* YouTube Video Placeholder - Ready for future implementation */}
      <div className="video-section" style={{ display: 'none' }}>
        <h3>🎥 Video Tutorial</h3>
        <div className="video-placeholder">
          <p>Video content will be available soon!</p>
        </div>
      </div>

      {/* Recipe Footer */}
      <div className="recipe-footer">
        <div className="recipe-sharing">
          <h4>🫶 Share This Recipe</h4>
          <p>Love this recipe? Share it with family and friends to spread the delicious Puerto Rican tradition!</p>
        </div>
      </div>
    </div>
  );
};

export default RecipeDetailPage;
